import{_ as t,o as d,c as o,a0 as c}from"./chunks/framework.BQvjZmTX.js";const v=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/env-vars.md","filePath":"reference/env-vars.md"}'),r={name:"reference/env-vars.md"};function a(n,e,i,s,l,_){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><p>Process env vars arca itself reads. (The vars in <code>[secrets]</code> are yours — this is arca&#39;s own surface; <code>arca manifest</code> reports the same table.)</p><table tabindex="0"><thead><tr><th>var</th><th>default</th><th>used for</th></tr></thead><tbody><tr><td><code>ARCA_CONFIG</code></td><td>—</td><td>config file override, between <code>--config</code> and <code>./arca.toml</code> in the search order</td></tr><tr><td><code>ARCA_ENV</code></td><td><code>dev</code></td><td>env context — resolution + routing (<code>--env</code> wins)</td></tr><tr><td><code>ARCA_ACTOR</code></td><td><code>$USER</code> → <code>anon</code></td><td>audit attribution (<code>--actor</code> wins). Self-claimed</td></tr><tr><td><code>ARCA_IDENTITY_FILE</code></td><td><code>~/.config/arca/identity.txt</code></td><td>age identity keyfile for every vault impl — pins file mode outright</td></tr><tr><td><code>ARCA_IDENTITY_BACKEND</code></td><td><code>keyring</code></td><td><code>keyring</code> (default — fail closed, no file fallback) | <code>auto</code> (keyring → keyfile fallback, for headless) | <code>file</code> (never probe the keyring); wins over <code>[identity] backend</code></td></tr><tr><td><code>ARCA_CF_TOKEN</code></td><td>—</td><td>bearer token for <code>kind = &quot;cf&quot;</code> vaults — <em>default</em> name; <code>[vaults.*].token_env</code> picks another</td></tr><tr><td><code>CLOUDFLARE_API_TOKEN</code></td><td>—</td><td>API token for <code>cf-secrets-store</code> deploy sinks — <em>default</em> name; <code>[deploy.*].token_env</code> picks another</td></tr><tr><td><code>ARCA_AUDIT_STDERR</code></td><td>on</td><td><code>0</code>/<code>false</code>/<code>off</code>/<code>no</code> silences the stderr ndjson audit wire — OTLP-only mode</td></tr><tr><td><code>OTEL_EXPORTER_OTLP_ENDPOINT</code></td><td>—</td><td>OTLP/HTTP collector base — audit events export as <code>arca.&lt;op&gt;</code> spans to <code>&lt;endpoint&gt;/v1/traces</code></td></tr><tr><td><code>OTEL_EXPORTER_OTLP_HEADERS</code></td><td>—</td><td><code>k=v,k2=v2</code> auth headers for the OTLP endpoint (values percent-decoded)</td></tr><tr><td><code>OTEL_EXPORTER_OTLP_TIMEOUT</code></td><td><code>10000</code></td><td>export timeout in ms</td></tr><tr><td><code>OTEL_SERVICE_NAME</code></td><td><code>arca</code></td><td><code>service.name</code> resource attribute on exported spans</td></tr><tr><td><code>OTEL_SDK_DISABLED</code></td><td>—</td><td><code>true</code>/<code>1</code> disables OTLP export entirely</td></tr></tbody></table><p>Honored XDG paths (when the matching override is unset):</p><table tabindex="0"><thead><tr><th>var</th><th>falls back to</th></tr></thead><tbody><tr><td><code>XDG_CONFIG_HOME</code></td><td><code>~/.config</code> — identity + user-level <code>arca.toml</code></td></tr><tr><td><code>XDG_DATA_HOME</code></td><td><code>~/.local/share</code> — the default <code>vault.age</code></td></tr></tbody></table><p>Two rules of thumb:</p><ul><li><code>token_env</code> config fields name env vars — the token <em>value</em> only ever lives in the process env.</li><li><code>ARCA_ACTOR</code> is a self-claimed string for the audit trail, not authentication; see the <a href="./../explanation/threat-model.html">threat model</a>.</li></ul>',7)])])}const h=t(r,[["render",a]]);export{v as __pageData,h as default};
